function route({ ticket, ticketId, fieldId, comment }) {
  if (ticket?.id !== ticketId || !Array.isArray(ticket?.raw?.custom_fields))
    throw Error("Ticket ID or custom fields invalid");
  const matches = ticket.raw.custom_fields.filter((x) => x?.id === fieldId);
  if (matches.length !== 1) throw Error("Configured GitHub issue field is absent or duplicated");
  const value = matches[0].value;
  if (value == null || value === "") {
    if (typeof ticket.subject !== "string" || !ticket.subject.trim())
      throw Error("Ticket subject is missing");
    return { existing: false, issueNumber: 1, title: ticket.subject, comment: "-" };
  }
  const text = String(value);
  if (!/^\d+$/.test(text) || !Number.isSafeInteger(Number(text)) || Number(text) < 1)
    throw Error("Invalid stored GitHub issue number");
  if (!comment.trim()) throw Error("A comment is required for an existing issue");
  return { existing: true, issueNumber: Number(text), title: ticket.subject || "-", comment };
}

const r = $("Validate the ticket event").first().json;
return {
  json: route({
    ticket: { id: $json.id, subject: $json.subject, raw: $json },
    ticketId: r.ticketId,
    fieldId: r.fieldId,
    comment: r.comment,
  }),
};

function request({ body, secret, fieldId, owner, repo }) {
  if (typeof secret !== "string" || secret.length < 24 || body?.secret !== secret)
    throw Error("Invalid webhook secret");
  const rawId = body?.id;
  if (!((typeof rawId === "string" && /^\d+$/.test(rawId)) || typeof rawId === "number"))
    throw Error("Invalid ticket ID");
  const ticketId = Number(rawId);
  if (!Number.isSafeInteger(ticketId) || ticketId < 1) throw Error("Invalid ticket ID");
  if (
    !Number.isSafeInteger(fieldId) ||
    fieldId < 1 ||
    !owner ||
    owner === "YOUR_GITHUB_OWNER" ||
    !repo ||
    repo === "YOUR_GITHUB_REPO"
  )
    throw Error("Configure the custom field and GitHub repository");
  const comment = body?.comment;
  if (comment != null && typeof comment !== "string") throw Error("Invalid comment");
  return { ticketId, comment: comment ?? "", fieldId, owner, repo };
}

return {
  json: request({
    body: $json.body,
    secret: $env.ZENDESK_GITHUB_SECRET,
    fieldId: 0,
    owner: "YOUR_GITHUB_OWNER",
    repo: "YOUR_GITHUB_REPO",
  }),
};
